H.background();
const Ecat = P.Ecat, Ean = P.Ean; // standard reduction potentials, V
const Ecell = Ecat - Ean;
const v = H.plot2d({ xMin: -1, xMax: 3, yMin: -2, yMax: 2 });
v.grid(); v.axes();
// zero (SHE) reference line
v.line(-1, 0, 3, 0, { color: H.colors.axis, width: 1, dash: [5, 5] });
v.text("SHE = 0 V", -0.6, 0.12);
// cathode level (x=1) and anode level (x=2) as horizontal markers
v.line(0.6, Ecat, 1.4, Ecat, { color: H.colors.accent2, width: 4 });
v.line(1.6, Ean, 2.4, Ean, { color: H.colors.sub, width: 4 });
v.text("cathode E = " + Ecat.toFixed(2) + " V", 1.0, Ecat + (Ecat >= 0 ? 0.18 : -0.22));
v.text("anode E = " + Ean.toFixed(2) + " V", 2.0, Ean + (Ean >= 0 ? 0.18 : -0.22));
// animated bar showing Ecell = difference, drawn as a growing/pulsing vertical span at x=2.7
const grow = 0.5 + 0.5 * Math.sin(t * 1.2); // 0..1 pulse, loops
const ytop = Math.max(Ecat, Ean), ybot = Math.min(Ecat, Ean);
const yfill = ybot + (ytop - ybot) * grow;
v.line(2.7, ybot, 2.7, yfill, { color: Ecell >= 0 ? H.colors.good : H.colors.warn, width: 8 });
v.dot(2.7, yfill, { r: 6, fill: Ecell >= 0 ? H.colors.good : H.colors.warn });
v.text("dE", 2.85, (Ecat + Ean) / 2);
// arrow from anode level to cathode level showing the gap
v.arrow(1.5, Ean, 1.5, Ecat, { color: H.colors.violet, width: 2 });
H.text("Standard cell potential:  E_cell = E_cathode - E_anode", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Both are reduction potentials; the more positive one is the cathode", 24, 52, { color: H.colors.sub, size: 13 });
H.text("E_cat = " + Ecat.toFixed(2) + " V,  E_an = " + Ean.toFixed(2) + " V", 24, 80, { color: H.colors.sub, size: 13 });
H.text("E_cell = " + Ecat.toFixed(2) + " - (" + Ean.toFixed(2) + ") = " + Ecell.toFixed(2) + " V", 24, 98, { color: Ecell >= 0 ? H.colors.good : H.colors.warn, size: 14, weight: 700 });
H.text(Ecell > 0 ? "E_cell > 0 -> galvanic (spontaneous, dG<0)" : (Ecell < 0 ? "E_cell < 0 -> electrolytic (non-spontaneous)" : "E_cell = 0 -> at equilibrium"), 24, 116, { color: H.colors.sub, size: 13 });
